mapper.select:
SELECT * FROM tb_experiment_report
WHERE experiment_id = #{experimentId}
ORDER BY submit_time DESC

mapper.insert:
INSERT INTO tb_experiment_report (
    experiment_id, student_id, student_name, student_number,
    content, files, submit_time, status
) VALUES (
    #{experimentId}, #{studentId}, #{studentName}, #{studentNumber},
    #{content}, #{files}, #{submitTime}, #{status}
)

mapper.update:
UPDATE tb_experiment_report
SET content = #{content},
    files = #{files},
    submit_time = #{submitTime},
    status = #{status}
WHERE id = #{id}
